insert into public.ce_course1_resources(id,data) values
 ('benzodiazepines_pdf','{"base64": "", "sha256": "397c568b27a73d82508b247d4f0f73294e7c5bf59d1058855ad56df21bc367f3", "filename": "CE_HALO_Benzodiazepines_Learner_FINAL.pdf", "mime_type": "application/pdf"}'::jsonb),
 ('benzodiazepines_questions','[{"module_id": "course_1_module_3", "question_id": "benzo_01", "question_number": 1, "stem": "Benzodiazepines produce their sedative and anxiolytic effects primarily by:", "correct_choice": "a", "rationale": "Benzodiazepines are positive allosteric modulators. They do not directly open the chloride channel; they increase the frequency of channel opening in the presence of GABA (Peter, Dieudonné, & Zolk, 2024).", "source_ids": [1], "learning_objective_ids": [1], "choice_a": "Increasing the frequency of GABA-A chloride channel opening in the presence of endogenous GABA", "choice_b": "Directly opening the GABA-A chloride channel without endogenous GABA", "choice_c": "Antagonizing NMDA receptors in the cortex", "choice_d": "Blocking presynaptic reuptake of glutamate", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://doi.org/10.3390/ph17040473"]}, {"module_id": "course_1_module_3", "question_id": "benzo_02", "question_number": 2, "stem": "Which benzodiazepine is hydrolyzed predominantly by carboxylesterase-1 (CES1), rather than relying on CYP3A metabolism?", "correct_choice": "b", "rationale": "Remimazolam undergoes carboxylesterase-mediated metabolism to inactive CNS7054. Severe hepatic impairment can still reduce clearance; it is not completely organ-independent.", "source_ids": [3, 4], "learning_objective_ids": [2], "choice_a": "Midazolam", "choice_b": "Remimazolam", "choice_c": "Diazepam", "choice_d": "Lorazepam", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://www.accessdata.fda.gov/drugsatfda_docs/label/2021/212295s002lbl.pdf", "https://doi.org/10.1007/s13318-025-00963-2"]}, {"module_id": "course_1_module_3", "question_id": "benzo_03", "question_number": 3, "stem": "A healthy 45-year-old adult receives midazolam for preoperative anxiolysis. Which IV dosing range is most appropriate as an initial approach?", "correct_choice": "c", "rationale": "For a healthy adult younger than 60, 1–2.5 mg is a reasonable initial titration range, with the initial increment no greater than 2.5 mg over at least 2 minutes and at least 2 additional minutes for reassessment. Lower doses may be needed with co-sedatives.", "source_ids": [2], "learning_objective_ids": [3], "choice_a": "0.05–0.1 mg IV once", "choice_b": "5–10 mg slow IV push", "choice_c": "1–2.5 mg slow IV, titrated with reassessment", "choice_d": "0.5 mg/kg IV bolus", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "d"], "remaining_choices": ["a", "c"]}, "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=94e1342b-f597-44c0-b8fc-b753fde04cbe"]}, {"module_id": "course_1_module_3", "question_id": "benzo_04", "question_number": 4, "stem": "According to Tsze et al. (2025), which intranasal midazolam doses were identified as optimal for procedural sedation in children undergoing laceration repair?", "correct_choice": "d", "rationale": "The laceration-repair trial retained 0.4 and 0.5 mg/kg intranasal doses (maximum 10 mg) and eliminated 0.2 and 0.3 mg/kg for lower effectiveness. Adequate sedation occurred in approximately 65%–70% with the retained doses; this is not a universal dose recommendation.", "source_ids": [6], "learning_objective_ids": [3], "choice_a": "0.1 mg/kg and 0.2 mg/kg", "choice_b": "0.2 mg/kg and 0.3 mg/kg", "choice_c": "0.6 mg/kg and 0.8 mg/kg", "choice_d": "0.4 mg/kg and 0.5 mg/kg", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "source_urls": ["https://doi.org/10.1001/jamapediatrics.2025.2181"]}, {"module_id": "course_1_module_3", "question_id": "benzo_05", "question_number": 5, "stem": "For an 80-year-old debilitated patient requiring IV midazolam premedication, the most appropriate initial approach is:", "correct_choice": "a", "rationale": "A conservative 0.5–1 mg IV starting approach with slow titration and reassessment is appropriate for this vulnerable patient. The injection label limits the geriatric initial increment to 1.5 mg over at least 2 minutes, followed by at least 2 more minutes to assess effect.", "source_ids": [2], "learning_objective_ids": [3, 4], "choice_a": "0.5–1 mg IV titrated carefully", "choice_b": "2.5–5 mg IV bolus", "choice_c": "0.15 mg/kg IV bolus", "choice_d": "Avoid all benzodiazepines entirely", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=94e1342b-f597-44c0-b8fc-b753fde04cbe"]}, {"module_id": "course_1_module_3", "question_id": "benzo_06", "question_number": 6, "stem": "The initial adult flumazenil dose recommended for reversal of procedural sedation is:", "correct_choice": "b", "rationale": "Adult reversal starts with 0.2 mg IV over 15 seconds. If needed, wait an additional 45 seconds before another 0.2 mg; subsequent 0.2-mg doses may be given at 60-second intervals to a maximum cumulative 1 mg.", "source_ids": [5], "learning_objective_ids": [3], "choice_a": "0.05 mg IV over 5 seconds", "choice_b": "0.2 mg IV over 15 seconds", "choice_c": "1 mg IV bolus", "choice_d": "0.01 mg/kg IV over 60 seconds", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ea41cbe-bc07-4c95-8bb2-7dfc2e96a874"]}, {"module_id": "course_1_module_3", "question_id": "benzo_07", "question_number": 7, "stem": "A child aged 1–17 years requires reversal of benzodiazepine-induced conscious sedation. What is the labeled initial IV flumazenil dose?", "correct_choice": "c", "rationale": "Give 0.01 mg/kg IV over 15 seconds, maximum 0.2 mg. Initial titration may continue within labeled intervals and a cumulative limit of 0.05 mg/kg or 1 mg, whichever is lower. Later repeated treatment for pediatric re-sedation is not established.", "source_ids": [5], "learning_objective_ids": [3], "choice_a": "0.05 mg/kg IV bolus", "choice_b": "0.1 mg/kg IV over 60 sec", "choice_c": "0.01 mg/kg IV over 15 sec (maximum 0.2 mg per dose)", "choice_d": "0.5 mg IV fixed dose regardless of weight", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "d"], "remaining_choices": ["a", "c"]}, "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ea41cbe-bc07-4c95-8bb2-7dfc2e96a874"]}, {"module_id": "course_1_module_3", "question_id": "benzo_08", "question_number": 8, "stem": "Which of the following is the most important reason to continue monitoring a patient after flumazenil reversal?", "correct_choice": "d", "rationale": "Flumazenil''s clinical duration is often shorter than the reversed benzodiazepine — particularly with long-acting agents or continuous infusions — so recurrent sedation and respiratory depression may occur. Reversal does not treat coadministered opioids.", "source_ids": [5], "learning_objective_ids": [3, 5], "choice_a": "Flumazenil causes prolonged amnesia beyond the benzodiazepine", "choice_b": "Flumazenil frequently causes malignant hyperthermia", "choice_c": "Flumazenil reverses concurrent opioids", "choice_d": "Flumazenil''s duration may be shorter than the benzodiazepine, allowing re-sedation", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ea41cbe-bc07-4c95-8bb2-7dfc2e96a874"]}, {"module_id": "course_1_module_3", "question_id": "benzo_09", "question_number": 9, "stem": "The 2025 APSF Brain Health Patient Safety Priority Advisory Group concluded that in older adults:", "correct_choice": "a", "rationale": "The 2025 APSF Brain Health advisory (Field et al., 2025) states that preoperative doses of short-acting (midazolam) or ultra-short-acting (remimazolam) benzodiazepines need not be proscriptively avoided in older adults, based on the current evidence.", "source_ids": [7], "learning_objective_ids": [5], "choice_a": "Preoperative doses of short- or ultra-short-acting benzodiazepines need not be proscriptively avoided if the goal is to minimize POD", "choice_b": "All benzodiazepines must be permanently avoided perioperatively", "choice_c": "Benzodiazepines eliminate postoperative delirium risk", "choice_d": "Only diazepam is acceptable for premedication", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://www.apsf.org/wp-content/uploads/newsletters/2025/4003/APSF4003-a07-Perioperative-Brain-Health.pdf"]}, {"module_id": "course_1_module_3", "question_id": "benzo_10", "question_number": 10, "stem": "Xi et al. (2025) pooled 11 studies, including randomized trials and cohorts, with varying control sedatives. Which secondary-outcome finding favored remimazolam?", "correct_choice": "b", "rationale": "The pooled review reported lower odds of hypotension (OR 0.29; 95% CI 0.20–0.42) and bradycardia (OR 0.19; 95% CI 0.05–0.76), without a statistically significant reduction in postoperative delirium. The evidence was not 11 exclusively propofol-controlled RCTs.", "source_ids": [10], "learning_objective_ids": [2, 5], "choice_a": "Higher risk of hypotension with remimazolam", "choice_b": "Lower odds of hypotension (OR 0.29; 95% CI 0.20–0.42) and bradycardia (OR 0.19) with remimazolam", "choice_c": "Significantly greater risk of postoperative delirium with remimazolam", "choice_d": "No differences in any secondary outcome", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://doi.org/10.1186/s13741-025-00589-7"]}, {"module_id": "course_1_module_3", "question_id": "benzo_11", "question_number": 11, "stem": "A 46-year-old on chronic clonazepam for panic disorder missed his morning dose. Preoperatively he is tachycardic, anxious, and tremulous. The most appropriate CRNA action is to:", "correct_choice": "c", "rationale": "Chronic benzodiazepine users can develop severe withdrawal (agitation, autonomic instability, delirium) with abrupt discontinuation (Yamaguchi et al., 2024). Continuation of baseline therapy or planned substitution is generally safer than unplanned discontinuation.", "source_ids": [13], "learning_objective_ids": [4, 5], "choice_a": "Cancel the case indefinitely", "choice_b": "Administer flumazenil to test dependence", "choice_c": "Continue baseline benzodiazepine therapy or provide equivalent substitution to prevent withdrawal", "choice_d": "Restrict all sedatives and proceed with general anesthesia", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "d"], "remaining_choices": ["a", "c"]}, "source_urls": ["https://doi.org/10.1002/pcn5.70026"]}, {"module_id": "course_1_module_3", "question_id": "benzo_12", "question_number": 12, "stem": "Which statement best describes the 2023 Wang et al. BJA meta-analysis findings on perioperative benzodiazepines and postoperative delirium?", "correct_choice": "d", "rationale": "The overall RR was 1.43 (95% CI 0.90–2.27), with very low certainty. This does not prove no harm. The dexmedetomidine comparison favored dexmedetomidine (RR 1.83; 95% CI 1.24–2.72 for benzodiazepines).", "source_ids": [8], "learning_objective_ids": [5], "choice_a": "Benzodiazepines significantly increased POD in all populations", "choice_b": "Benzodiazepines eliminated intraoperative awareness with no other effect", "choice_c": "Benzodiazepines were superior to propofol in preventing POD", "choice_d": "No statistically significant overall POD difference was found; risk was higher versus dexmedetomidine", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "source_urls": ["https://doi.org/10.1016/j.bja.2023.04.017"]}, {"module_id": "course_1_module_3", "question_id": "benzo_13", "question_number": 13, "stem": "An OSA patient with obesity and chronic opioid therapy is scheduled for endoscopy under MAC. Which sedation strategy is most appropriate?", "correct_choice": "a", "rationale": "In obesity + OSA + chronic opioid patients, benzodiazepines are risk-amplifying rather than benign. The safest approach minimizes or omits benzodiazepines and emphasizes airway preparation, capnography, opioid-sparing, and enhanced observation (Tracy et al., 2025).", "source_ids": [14], "learning_objective_ids": [4], "choice_a": "Minimize or avoid benzodiazepines, emphasize capnography, opioid-sparing plan, airway positioning, and enhanced monitoring", "choice_b": "Full-dose midazolam plus fentanyl bolus at start", "choice_c": "Administer flumazenil prophylactically after induction", "choice_d": "Use a fixed 5 mg midazolam premedication regardless of comorbidities", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://doi.org/10.1080/20565623.2025.2540744"]}, {"module_id": "course_1_module_3", "question_id": "benzo_14", "question_number": 14, "stem": "In pregnancy, perioperative benzodiazepine use should generally follow which principle?", "correct_choice": "b", "rationale": "Benzodiazepines cross the placenta. Bais et al. (2024) support a risk-benefit approach: use the lowest effective dose, avoid unnecessary repeat dosing, and coordinate care when clinically significant exposure is expected.", "source_ids": [15], "learning_objective_ids": [4], "choice_a": "Absolute contraindication throughout all trimesters", "choice_b": "Lowest effective dose, avoid unnecessary repeated dosing, and coordinate with obstetric/neonatal teams for significant exposure", "choice_c": "Routine high-dose use to reduce maternal stress", "choice_d": "Prefer diazepam because of its long half-life", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://doi.org/10.1007/s00404-024-07515-0"]}, {"module_id": "course_1_module_3", "question_id": "benzo_15", "question_number": 15, "stem": "A postoperative lactating patient asks when she can resume breastfeeding after a single 2 mg midazolam preoperative dose. The best answer based on 2024 ASA guidance is:", "correct_choice": "c", "rationale": "The 2024 ASA Statement on Resuming Breastfeeding After Anesthesia indicates most anesthetic and sedative medications do not require routine ''pump and dump.'' After short-term perioperative benzodiazepine exposure, breastfeeding can resume once the patient is awake, alert, and able to hold the infant safely.", "source_ids": [16], "learning_objective_ids": [4], "choice_a": "Discard breast milk for 24 hours before resuming", "choice_b": "Discontinue breastfeeding permanently", "choice_c": "Resume breastfeeding once she is awake, alert, and able to safely hold the infant", "choice_d": "Pump and dump for 72 hours regardless of dose", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "d"], "remaining_choices": ["a", "c"]}, "source_urls": ["https://www.asahq.org/standards-and-practice-parameters/statement-on-resuming-breastfeeding-after-anesthesia"]}, {"module_id": "course_1_module_3", "question_id": "benzo_16", "question_number": 16, "stem": "Which statement best describes remimazolam in a patient with severe hepatic impairment?", "correct_choice": "d", "rationale": "Remimazolam is metabolized predominantly through carboxylesterases, including hepatic CES1. Severe hepatic impairment can prolong recovery; titrate carefully and consider less frequent supplemental doses.", "source_ids": [3, 4], "learning_objective_ids": [2, 4], "choice_a": "Its clearance cannot be affected because all esterases are outside the liver", "choice_b": "Normal adult doses guarantee normal recovery time", "choice_c": "Renal excretion of unchanged drug is the main determinant of clearance", "choice_d": "Carboxylesterase metabolism avoids major CYP involvement, but severe hepatic impairment can slow clearance", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "source_urls": ["https://www.accessdata.fda.gov/drugsatfda_docs/label/2021/212295s002lbl.pdf", "https://doi.org/10.1007/s13318-025-00963-2"]}, {"module_id": "course_1_module_3", "question_id": "benzo_17", "question_number": 17, "stem": "In Zhang et al. (2025), the five-RCT emergence-delirium analysis compared remimazolam with placebo/saline or sevoflurane alone. RR 0.39 corresponds to approximately what relative reduction?", "correct_choice": "a", "rationale": "RR 0.39 corresponds to a 61% relative reduction (95% CI for RR 0.21–0.70). This emergence-delirium analysis did not use propofol as its comparator and does not establish a U.S. pediatric indication.", "source_ids": [11], "learning_objective_ids": [4, 5], "choice_a": "61%", "choice_b": "10%", "choice_c": "25%", "choice_d": "45%", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://doi.org/10.3389/fped.2025.1662752"]}, {"module_id": "course_1_module_3", "question_id": "benzo_18", "question_number": 18, "stem": "Which of the following situations warrants the greatest caution before giving flumazenil?", "correct_choice": "b", "rationale": "Dependence and mixed overdose increase withdrawal or seizure concerns. Flumazenil is contraindicated when there are signs of serious cyclic-antidepressant overdose or when a benzodiazepine is controlling a life-threatening condition such as status epilepticus.", "source_ids": [5], "learning_objective_ids": [5], "choice_a": "Isolated benzodiazepine sedation in a healthy adult", "choice_b": "Chronic benzodiazepine user or suspected mixed overdose with tricyclic exposure or seizure risk", "choice_c": "Delayed emergence after a single midazolam premedication dose", "choice_d": "Adult receiving flumazenil for procedural sedation reversal", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ea41cbe-bc07-4c95-8bb2-7dfc2e96a874"]}, {"module_id": "course_1_module_3", "question_id": "benzo_19", "question_number": 19, "stem": "The 2026 Zhou et al. review of remimazolam-flumazenil reversal reported that re-sedation may occur in approximately:", "correct_choice": "c", "rationale": "The narrative review summarizes heterogeneous re-sedation rates around 2%–22%. Settings, definitions, doses, and exposure duration differ. Continue monitoring; initial arousal does not guarantee sustained recovery.", "source_ids": [12], "learning_objective_ids": [5], "choice_a": "<1% of cases", "choice_b": "50–80% of cases universally", "choice_c": "Approximately 2%–22% across heterogeneous study settings, not a universal patient risk", "choice_d": "Only after propofol co-administration", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "d"], "remaining_choices": ["a", "c"]}, "source_urls": ["https://doi.org/10.3389/fmed.2026.1793528"]}, {"module_id": "course_1_module_3", "question_id": "benzo_20", "question_number": 20, "stem": "A 6-year-old child requires IV midazolam for procedural sedation. The typical initial IV dose is:", "correct_choice": "d", "rationale": "For children 6–12 years, initial IV midazolam is 0.025–0.05 mg/kg IV, cumulative up to about 0.4 mg/kg (usual max ~10 mg), titrated with close airway and ventilation monitoring, especially if opioids are coadministered.", "source_ids": [2], "learning_objective_ids": [3, 4], "choice_a": "0.005 mg/kg IV bolus", "choice_b": "0.2 mg/kg IV push", "choice_c": "1 mg/kg IV bolus", "choice_d": "0.025–0.05 mg/kg IV initially, titrated to effect", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=94e1342b-f597-44c0-b8fc-b753fde04cbe"]}, {"module_id": "course_1_module_3", "question_id": "benzo_21", "question_number": 21, "stem": "Which statement about long-term versus preoperative benzodiazepine exposure in older adults is most consistent with the 2025 Starks et al. BioCog analysis?", "correct_choice": "a", "rationale": "In 928 BioCog participants, long-term use was associated with POD (p < 0.001), while immediate preoperative premedication was not significantly associated (p = 0.242). This observational analysis does not establish causation or prove universal safety.", "source_ids": [9], "learning_objective_ids": [5], "choice_a": "Long-term use was associated with POD, but immediate preoperative premedication was not significantly associated", "choice_b": "Both long-term use and single preoperative doses similarly increase POD", "choice_c": "Only preoperative premedication drives POD; long-term use is protective", "choice_d": "Neither long-term nor preoperative use has any effect on POD", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://doi.org/10.1097/EJA.0000000000002201"]}, {"module_id": "course_1_module_3", "question_id": "benzo_22", "question_number": 22, "stem": "An 82-year-old anxious patient with mild cognitive impairment is scheduled for hip fracture repair. The surgical team requests IV midazolam premedication. The most appropriate CRNA response is to:", "correct_choice": "b", "rationale": "The 2025 APSF Brain Health advisory supports individualized decisions. A reduced titrated dose or nonpharmacologic strategies is often the best balance in a frail older adult with baseline cognitive impairment.", "source_ids": [2, 7], "learning_objective_ids": [4, 5], "choice_a": "Refuse all benzodiazepines and proceed with induction", "choice_b": "Consider a reduced dose (0.5–1 mg IV) or nonpharmacologic anxiolysis, individualized to frailty and cognition", "choice_c": "Give a 5 mg midazolam bolus to eliminate anxiety completely", "choice_d": "Administer flumazenil prophylactically before induction", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=94e1342b-f597-44c0-b8fc-b753fde04cbe", "https://www.apsf.org/wp-content/uploads/newsletters/2025/4003/APSF4003-a07-Perioperative-Brain-Health.pdf"]}, {"module_id": "course_1_module_3", "question_id": "benzo_23", "question_number": 23, "stem": "Which statement about remimazolam pharmacokinetics is correct?", "correct_choice": "c", "rationale": "Remimazolam has a terminal half-life of approximately 37–53 minutes and clearance significantly higher than midazolam. It is CES1-metabolized and can be antagonized by flumazenil (Murrell & Harirforoosh, 2025).", "source_ids": [3, 4], "learning_objective_ids": [2], "choice_a": "It is metabolized primarily via renal excretion", "choice_b": "Its clearance is markedly lower than midazolam", "choice_c": "Terminal half-life is approximately 37–53 minutes", "choice_d": "It cannot be antagonized by flumazenil", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "d"], "remaining_choices": ["a", "c"]}, "source_urls": ["https://www.accessdata.fda.gov/drugsatfda_docs/label/2021/212295s002lbl.pdf", "https://doi.org/10.1007/s13318-025-00963-2"]}, {"module_id": "course_1_module_3", "question_id": "benzo_24", "question_number": 24, "stem": "A child becomes sedated again after initially successful flumazenil reversal. Which statement is most appropriate?", "correct_choice": "d", "rationale": "The label distinguishes initial pediatric titration from later repeat administration for re-sedation. The latter is not established. Continue observation and ventilatory support as needed, with individualized expert management.", "source_ids": [5], "learning_objective_ids": [3, 5], "choice_a": "Automatically repeat the adult 20-minute regimen", "choice_b": "Discharge because initial reversal proves the benzodiazepine effect is gone", "choice_c": "Flumazenil will reverse any co-administered opioid", "choice_d": "Support and monitor the airway; safety and efficacy of repeat flumazenil treatment for pediatric re-sedation are not established", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["b", "c"], "remaining_choices": ["a", "d"]}, "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/drugInfo.cfm?setid=3ea41cbe-bc07-4c95-8bb2-7dfc2e96a874"]}, {"module_id": "course_1_module_3", "question_id": "benzo_25", "question_number": 25, "stem": "Which statement best summarizes the CRNA''s overall approach to perioperative benzodiazepine management in 2025–2026?", "correct_choice": "a", "rationale": "Current best practice — grounded in Wang 2023, Ge 2025, Starks 2025, and the 2025 APSF Brain Health advisory — is individualized use rather than blanket avoidance or reflexive dosing. The core CRNA skill is matching agent, dose, and monitoring to the specific patient and documenting the reasoning.", "source_ids": [2, 7], "learning_objective_ids": [4, 5], "choice_a": "Individualize agent selection, dose, and monitoring based on age, comorbidities, chronic use, and procedural context; document reasoning", "choice_b": "Apply a single fixed premedication dose to every adult regardless of comorbidity", "choice_c": "Universally avoid all benzodiazepines in all populations", "choice_d": "Reverse every benzodiazepine dose with flumazenil at end of case", "hint": {"mode": "eliminate_two_wrong_answers", "eliminate_choices": ["c", "d"], "remaining_choices": ["a", "b"]}, "source_urls": ["https://dailymed.nlm.nih.gov/dailymed/fda/fdaDrugXsl.cfm?setid=94e1342b-f597-44c0-b8fc-b753fde04cbe", "https://www.apsf.org/wp-content/uploads/newsletters/2025/4003/APSF4003-a07-Perioperative-Brain-Health.pdf"]}]'::jsonb)
